import type { QuizVideoProps } from './schema.js';

export type QuizNarrationTexts = {
    intro: string; question: string; countdown: string; reveal: string; explanation: string | null; outro: string;
};

// Deterministic, templated narration text — never generated by an AI model. The question, its
// propositions and its explanation always travel through verbatim from `quiz` (itself built from
// the exact RijPermis source in build.ts); only the fixed surrounding phrases are authored here.
export function buildQuizNarration(quiz: QuizVideoProps): QuizNarrationTexts {
    const seconds = Math.max(1, Math.round(quiz.durations.countdownSeconds));
    const correct = quiz.options.find(option => option.id === quiz.correctOptionId);
    if (!correct) throw new Error('CORRECT_OPTION_NOT_FOUND');

    if (quiz.language === 'nl') {
        return {
            intro: `${quiz.brand.name}, de quiz van de dag.`,
            question: `${quiz.source.category}. ${quiz.question} ${quiz.options.map(option => `${option.id}: ${option.text}.`).join(' ')}`,
            countdown: `Je hebt ${seconds} seconden om na te denken.`,
            reveal: `Het juiste antwoord is ${correct.id}: ${correct.text}.`,
            explanation: quiz.explanation,
            outro: `Oefen verder op ${quiz.brand.website}.`
        };
    }
    return {
        intro: `${quiz.brand.name}, le quiz du jour.`,
        question: `${quiz.source.category}. ${quiz.question} ${quiz.options.map(option => `${option.id} : ${option.text}.`).join(' ')}`,
        countdown: `Vous avez ${seconds} secondes pour réfléchir.`,
        reveal: `La bonne réponse est ${correct.id} : ${correct.text}.`,
        explanation: quiz.explanation,
        outro: `Entraînez-vous sur ${quiz.brand.website}.`
    };
}
